10	// this OS window to one of them by its active tab title, restore opens a new Chrome
11	// window with the saved urls, see docs/spikes/browser.md, registered before
12	// GenericAdapter so chrome.exe windows go here first
13	public sealed class BrowserAdapter : IAdapter
14	{
15	    private const string ChromeExe = "chrome.exe";
16	    private const string TitleSuffix = " - Google Chrome";
17	    // Capture runs on the UI thread, bound the wait so a missing extension does not
18	    // freeze it for long, a working extension answers in well under a second
19	    private static readonly TimeSpan QueryTimeout = TimeSpan.FromSeconds(3);
20	    private static readonly TimeSpan CacheTtl = TimeSpan.FromSeconds(5);
21	
22	    private readonly Func<IReadOnlyList<BrowserWindow>> _queryWindows;
23	    private readonly IWindowWaiter _waiter;
24	    private readonly IWindowPlacer _placer;
25	    private readonly Action<string> _launch;
26	    private readonly Func<DateTime> _now;
27	
28	    // A capture touches every Chrome window, so the pipe query is cached briefly and
29	    // shared across those windows rather than re-run per window
30	    private IReadOnlyList<BrowserWindow>? _cache;
31	    private string? _cacheError;
32	    private DateTime _cachedAt;
33	
34	    public BrowserAdapter()
35	        : this(() => BrowserTabsClient.Query(QueryTimeout), new WindowWaiter(), new WindowPlacer(), LaunchChrome, () => DateTime.UtcNow) { }
36	
37	    public BrowserAdapter(
38	        Func<IReadOnlyList<BrowserWindow>> queryWindows,
39	        IWindowWaiter waiter,
40	        IWindowPlacer placer,
41	        Action<string> launch,
42	        Func<DateTime> now)
43	    {
