103	    // Matches an OS window title ("<active tab> - Google Chrome") to a reported
104	    // window by its active tab title, falls back to the only window when there is
105	    // one, returns null when the match is absent or ambiguous
106	    public static IReadOnlyList<string>? MatchUrls(string windowTitle, IReadOnlyList<BrowserWindow> windows)
107	    {
108	        if (windows.Count == 0)
109	        {
110	            return null;
111	        }
112	
113	        string active = StripSuffix(windowTitle);
114	        List<BrowserWindow> matches = windows
115	            .Where(w => string.Equals(w.Title, active, StringComparison.Ordinal))
116	            .ToList();
117	
118	        if (matches.Count == 1)
119	        {
120	            return matches[0].Urls;
121	        }
122	
123	        if (matches.Count == 0 && windows.Count == 1)
124	        {
125	            return windows[0].Urls;
126	        }
127	
128	        return null;
