136	    private IReadOnlyList<BrowserWindow> CachedQuery()
137	    {
138	        bool fresh = _now() - _cachedAt < CacheTtl && (_cache is not null || _cacheError is not null);
139	        if (!fresh)
140	        {
141	            try
142	            {
143	                _cache = _queryWindows();
144	                _cacheError = null;
145	            }
146	            catch (BrowserUnavailableException ex)
147	            {
148	                _cache = null;
149	                _cacheError = ex.Message;
150	            }
151	
152	            _cachedAt = _now();
153	        }
154	
155	        if (_cacheError is not null)
156	        {
157	            throw new CaptureException(_cacheError);
