172	    private static string DisplayNameFor(string windowTitle, IReadOnlyList<string> urls)
173	    {
174	        string label = StripSuffix(windowTitle);
175	        if (string.IsNullOrWhiteSpace(label))
176	        {
177	            label = "Chrome";
178	        }
179	
180	        return urls.Count <= 1 ? $"Chrome - {label}" : $"Chrome - {label} +{urls.Count - 1}";
181	    }
