189	    // Chrome's standard install locations, first that exists wins
190	    private static string? ChromePath()
191	    {
192	        string[] candidates =
193	        {
194	            Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles), "Google", "Chrome", "Application", "chrome.exe"),
