7	// Chrome native messaging framing, each message is a 4-byte little-endian length
8	// then that many bytes of UTF-8 JSON, the same framing is used on the named pipe
9	// between the host and the app, see docs/spikes/browser.md
10	public static class NativeMessaging
11	{
12	    // Chrome caps a single host-to-extension message at 1 MB, guard against a
13	    // bogus length prefix allocating wildly
14	    public const int MaxMessageBytes = 1024 * 1024;
15	
16	    public static void WriteFrame(Stream destination, string json)
17	    {
18	        ArgumentNullException.ThrowIfNull(destination);
19	        ArgumentNullException.ThrowIfNull(json);
20	
21	        byte[] data = Encoding.UTF8.GetBytes(json);
22	        Span<byte> prefix = stackalloc byte[4];
23	        BinaryPrimitives.WriteUInt32LittleEndian(prefix, (uint)data.Length);
24	
25	        destination.Write(prefix);
26	        destination.Write(data);
27	        destination.Flush();
28	    }
29	
30	    // Reads one frame, or null at a clean end of stream (the length prefix could
31	    // not be read in full), a partial body after a valid prefix is a broken stream
32	    public static string? ReadFrame(Stream source)
33	    {
34	        ArgumentNullException.ThrowIfNull(source);
35	
36	        byte[] prefix = new byte[4];
37	        if (!TryReadExactly(source, prefix))
38	        {
39	            return null;
40	        }
41	
42	        uint length = BinaryPrimitives.ReadUInt32LittleEndian(prefix);
43	        if (length == 0)
44	        {
45	            return string.Empty;
46	        }
47	
48	        if (length > MaxMessageBytes)
49	        {
50	            throw new InvalidDataException($"Native message length {length} exceeds the {MaxMessageBytes} byte cap.");
51	        }
52	
53	        byte[] data = new byte[length];
54	        if (!TryReadExactly(source, data))
55	        {
56	            throw new InvalidDataException("Native message ended before its declared length.");
57	        }
58	
59	        return Encoding.UTF8.GetString(data);
60	    }
61	
62	    // Reads buffer.Length bytes, looping because one read may return fewer, false
63	    // when the stream ends before the first byte of the buffer
64	    private static bool TryReadExactly(Stream source, byte[] buffer)
65	    {
66	        int read = 0;
67	        while (read < buffer.Length)
68	        {
69	            int n = source.Read(buffer, read, buffer.Length - read);
70	            if (n == 0)
71	            {
72	                if (read == 0)
73	                {
74	                    return false; // clean end of stream at a frame boundary
75	                }
76	
77	                throw new InvalidDataException("Native message stream ended mid-frame.");
78	            }
79	
80	            read += n;
81	        }
82	
83	        return true;
84	    }
85	}
